/** t() with {name} placeholders filled. */
export const tf = (lang, k, v = {}) => String(t(lang, k)).replace(/\{(\w+)\}/g, (_m, n) => (v[n] == null ? '' : String(v[n])));
/** "2 suppliers" / "مورّدان". Arabic counts take the dual at 2, the plural at 3-10 and the singular
 *  accusative from 11 (١١ مورّدًا), so one plural key would be wrong for most numbers. */
export function supplierCount(lang, n) {
  n = Number(n) || 0;
  if (n === 1) return t(lang, 'so_sup_one');
  if (lang === 'ar') return n === 2 ? t(lang, 'so_sup_two') : tf(lang, n >= 3 && n <= 10 ? 'so_sup_few' : 'so_sup_many', { n });
  return tf(lang, 'so_sup_many', { n });
}
export const EMIRATE_AR = { Dubai: 'دبي', 'Abu Dhabi': 'أبوظبي', Sharjah: 'الشارقة', Ajman: 'عجمان', 'Ras Al Khaimah': 'رأس الخيمة', 'Umm Al Quwain': 'أم القيوين', Fujairah: 'الفجيرة' };
export const emirateName = (e, lang) => (lang === 'ar' && EMIRATE_AR[e]) || e;

// A SERVER STRING IS NOT A SENTENCE IN THE CUSTOMER'S LANGUAGE. login_otp, kyc, customer_api and
// stripe_checkout answer in English, sometimes as a sentence and sometimes as a code
// ('stripe_not_configured' at HTTP 200), and the portal printed j.error verbatim. Codes and flags are
// matched first, then the fixed English sentences those functions send; anything unrecognised falls
// back to a localised generic line rather than to raw English or a snake_case code.
const CODE_KEY = {
  stripe_not_configured: 'err_stripe_nc', stripe_error: 'err_stripe', intake_required: 'nr_more_details', registration_incomplete: 'err_registration',
  account_incomplete: 'err_registration', dob_required: 'err_dob_required', dob_invalid: 'err_dob_invalid', under_18: 'err_under_18',
  unauthorized: 'session_expired', 'Not signed in': 'session_expired', text_required: 'err_text_required', inquiry_closed: 'err_closed',
  not_your_inquiry: 'err_not_yours', 'Not your inquiry': 'err_not_yours', already_answered: 'err_already_answered', too_many_questions: 'err_rate',
  too_many_notes: 'err_rate', refund_window_elapsed: 'err_refund_window', not_found: 'err_not_found', forbidden: 'err_not_yours',
  // customer_api rate_supplier, 17 Sep 2026: a refused rating comes back as a 4xx with a code, never
  // as the 500 that used to carry a raw constraint name to the customer.
  review_comment_too_short: 'err_review_comment', rating_out_of_range: 'err_rating_range',
  // reveal_invoice, 21 Sep 2026: no invoice or receipt for a payment that has not settled.
  payment_not_settled: 'q_inv_not_paid',
};
const MSG_KEY = [
  [/do-not-send/i, 'err_suppressed'], [/create an account from a mobile/i, 'signup_email_only'], [/not linked|No account is registered/i, 'err_mobile_unknown'],
  [/more than one/i, 'err_ambiguous'], [/SMS sign-in is not enabled/i, 'err_sms_off'], [/SMS is not configured/i, 'err_sms_nc'], [/Too many/i, 'err_too_many'],
  [/expired/i, 'err_expired'], [/Incorrect|Enter the (6-digit )?code|code you received/i, 'err_incorrect'], [/valid email address or UAE/i, 'err_invalid_id'],
  [/valid mobile/i, 'err_phone'], [/enter your name/i, 'err_name'], [/suspended/i, 'err_suspended'], [/verify your email/i, 'err_email_verify'],
  [/many requests|many PDFs|short time/i, 'err_rate'], [/already rated/i, 'err_refund_rated'], [/completed with this supplier/i, 'err_refund_hired'],
  [/window has elapsed/i, 'err_refund_window'], [/not found/i, 'err_not_found'], [/No customer profile/i, 'load_failed'],
];
export function errText(j, lang, fallbackKey = 'err_generic') {
  if (!j) return t(lang, fallbackKey);
  if (j.ambiguous) return t(lang, 'err_ambiguous');
  if (j.suppressed) return t(lang, 'err_suppressed');
  for (const c of [j.code, j.error]) if (c && CODE_KEY[String(c)]) return t(lang, CODE_KEY[String(c)]);
  const text = [j.error, j.message].filter(Boolean).join(' ');
  for (const [re, k] of MSG_KEY) if (re.test(text)) return t(lang, k);
  return t(lang, fallbackKey);
}
